+        if (_containsVoxelNode(value, depth: depth + 1)) return true;
+      }
+    } else if (node is List) {
+      for (final value in node) {
+        if (_containsVoxelNode(value, depth: depth + 1)) return true;
+      }
+    }
+    return false;
+  }
+
   /// Starts (or restarts) the JS engine with the current [entryFile].
   Future<void> start() => _guardLifecycle(_start);

