+      id: ID, position: [3, 3, 5], yaw: 0, pitch: 0, skyColor: '#87CEEB'
+    });
+  }).then(function() {
+    jsr.render({type: 'column', children: [
+      {type: 'text', data: 'TILE-VOXEL-READY'},
