    if (feedback == null || !feedback.deliver) return; // dedup / breaker
    JsAppErrorChannel.instance.publish(
      JsAppErrorNotice(
        event: event,
        appId: app.id,
        surface: entryFile == JsAppEngine.defaultEntryFile ? 'app' : 'tile',
        sourceRevision: sourceRevision,
        notice: feedback.notice,
