  group('pubVersion', () {
    test('parses a plain triple', () {
      expect(pubVersion('0.4.156'), pubVersion('0.4.156'));
    });

    test('tolerates a build-suffixed version', () {
      // "0.4.157+hotfix" is >= the plain 0.4.156 floor — must not throw.
