  if (_presentedThisRun.length >= maxPerRun) return null;
  final id = 'dm-${DateTime.now().microsecondsSinceEpoch.toRadixString(36)}';
  _presentedThisRun.add(id);
  await materialise(sessionId: sessionId, request: request, id: id);

