  'fullscreen app view': 'flutter_app/lib/apps/js_app_view.dart',
  'live widget tile': 'flutter_app/lib/apps/dynamic_widget_tile.dart',
  'launcher board tile': 'flutter_app/lib/apps/app_tile_host.dart',
};

